<?php
require '../config/app.php';require_role('technician');$title='Technician Workspace | DiagnosCare';$basePath='../';$tid=user()['id'];
$today=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE technician_id=? AND appointment_date=CURDATE()");$today->execute([$tid]);$today=$today->fetchColumn();
$pending=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE technician_id=? AND status IN ('Booked','Confirmed')");$pending->execute([$tid]);$pending=$pending->fetchColumn();
$completed=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE technician_id=? AND status='Completed'");$completed->execute([$tid]);$completed=$completed->fetchColumn();
$rows=$pdo->prepare("SELECT a.*,u.name patient_name,u.phone patient_phone,t.name test_name,r.result_status FROM appointments a JOIN users u ON u.id=a.patient_id JOIN diagnostic_tests t ON t.id=a.test_id LEFT JOIN test_results r ON r.appointment_id=a.id WHERE a.technician_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC LIMIT 10");$rows->execute([$tid]);$rows=$rows->fetchAll();
require '../partials/header.php';?>
