<div class="row g-3 mb-4"><?php foreach([[$today,'Today','bi-calendar-day'],[$pending,'Pending','bi-hourglass-split'],[$completed,'Completed','bi-check2-circle']] as $x):?><div class="col-md-4"><div class="card stat-card metric-card"><div class="d-flex justify-content-between"><div><small class="text-muted"><?=$x[1]?> appointments</small><h2 class="mt-2 mb-0"><?=$x[0]?></h2></div><div class="stat-icon"><i class="bi <?=$x[2]?>"></i></div></div></div></div><?php endforeach;?></div>

