<div id="queue" class="card table-card p-3"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h5 class="mb-1">My appointment queue</h5><small class="text-muted">Patients assigned to you.</small></div><input id="queueSearch" class="form-control" style="max-width:240px" placeholder="Search patient or test..."></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Patient</th><th>Test</th><th>Schedule</th><th>Result</th><th>Action</th></tr></thead><tbody id="queueRows"><?php foreach($rows as $r):?><tr><td><div class="d-flex gap-2 align-items-center"><div class="avatar"><?=e(strtoupper(substr($r['patient_name'],0,1)))?></div><div><strong><?=e($r['patient_name'])?></strong><div class="small text-muted"><?=e($r['patient_phone'] ?: 'No phone')?></div></div></div></td><td><?=e($r['test_name'])?></td><td><?=e($r['appointment_date'])?><div class="small text-muted"><?=date('h:i A',strtotime($r['appointment_time']))?></div></td><td><?=e($r['result_status']??'Pending')?></td><td><a class="btn btn-sm btn-primary" href="appointment.php?id=<?=$r['id']?>">Open Case</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><i class="bi bi-inbox fs-1"></i><h5 class="mt-3">No assigned appointments</h5><p>Your queue will appear here when the admin assigns a case.</p></div><?php endif;?></div>
</section></div><script>document.getElementById('queueSearch')?.addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('#queueRows tr').forEach(r=>r.classList.toggle('d-none',!r.innerText.toLowerCase().includes(q)))});</script><?php require '../partials/footer.php'; ?>